fn max_range_nearly_can_use(champ: &Entity, target: &Entity, tick: usize) -> u64   // battle.rs:2397
  let mut range = 0;                                                                  // 2398

  // 헬퍼(전부 인라인되어 본문에 녹아 있음)
  //   eff_range(e, who) = e.range + e.growth_range * (who.level - 1) + who.stat_buff_cached.range   // effect.rs:26
  //   radius(x)         = if x.stat_buff_cached.radius_mult == 0 { x.radius }
  //                       else { x.radius * (radius_mult + 100) / 100 }                              // entity.rs:1511~1515
  //   total(e) = eff_range(e, champ) + e.range_adjust(champ, target) + radius(champ) + radius(target)

  // ── 1) 평타 ─────────────────────────────────  2399~2403
  if champ.attack_effect.is_some()                       // Entity+0x4c0 != -1
     && effect.target.check(champ, target)               // CastingTarget::check
     && champ.attack_cooldown() <= tick {                // entity.rs:1747 match ty →
        //   ty=0 None / ty=3 Nexus → 쿨타임 필드 없음 = 0 (게이트 상수접힘, 항상 통과)
        //   ty=1 Minion +0xb8 / 2 Tower +0x110 / 4 Jungle +0xe8 / 5 Epic +0x1f0 /
        //   6 Serpen +0x1f0 / 7 Ghoul +0xe8 / 8 SmallJiangshi +0xb0 / 9 Bear +0xc8 /
        //   10 Eagle +0xf0 / 11 Revenant +0xd8 / 12 Illusion +0xd0 / 13 Champion +0xb0
      range = max(range, total(champ.attack_effect));    // 2403 (첫 항이라 max 가 접혀 대입만 남음)
  }

  // ── 2) 스킬 ─────────────────────────────────  2407~2410
  if champ.skill_effect.is_some()                        // Entity+0x4f8 != -1
     && effect.target.check(champ, target)
     && champ.skill_cooldown() <= tick {                 // entity.rs:1774: ty==Champion(13) 이면 +0xb8, 아니면 0
      range = max(range, total(champ.skill_effect));     // 2410 (llvm.umax.i64)
  }

  // ── 3) 스킬2 ────────────────────────────────  2414~2417
  let e2 = if champ.level > 2 { &champ.skill2_effect } else { &DUMMY_NONE };  // entity.rs:1693
  if e2.is_some()                                        // e2+48 != -1
     && e2.target.check(champ, target)
     && champ.skill2_cooldown() <= tick {                // entity.rs:1789: ty==13 이면 +0xc0, 아니면 0
      range = max(range, total(e2));                     // 2417
  }

  // ── 4) 궁 ──────────────────────────────────  2421~2424
  let eu = if champ.level > 4 { &champ.ult_effect } else { &DUMMY_NONE };     // entity.rs:1701
  if eu.is_some()
     && eu.target.check(champ, target)
     && champ.ult_cooldown() <= tick {                   // entity.rs:1804: ty==13 이면 +0xc8, 아니면 0
      range = max(range, total(eu));                     // 2424
  }

  range                                                                        // 2429

// 주의점 (IR 에서 직접 확인된 것)
// A. 네 블록은 완전히 독립적인 순차 if 이고 early-return 이 없다. 한 슬롯이 걸러져도 다음 슬롯은 그대로 평가된다.
// B. 쿨타임 게이트의 방향은 '남은쿨 > tick 이면 건너뛴다'(icmp ugt cooldown, tick). 즉 통과 조건은 cooldown <= tick.
// C. DUMMY_NONE = @anon.ff23c5838f81fa2a3acb125bb4b6e568.40 (48B undef + i32 0xFFFFFFFF) = 니치 판별자 -1 인 상수 Option::None.
//    level 미달이면 이 전역을 가리키게 select 해서 뒤 검사가 자연히 실패한다.
// D. skill/skill2/ult 의 쿨타임 게이트는 ty==Champion 일 때만 실효다. Revenant(ty=11)는 자기 구조체에
//    skill_cooldown/skill2_cooldown/ult_cooldown 필드를 갖고 있는데도 여기선 0 으로 취급되어 항상 '쓸 수 있음'이 된다.
//    (반대로 평타 쿨타임은 12개 variant 전부 제대로 읽는다.)
// E. target 엔티티는 사거리 합에 자기 radius 만 기여한다(+ check/range_adjust 인자). target 의 level·버프사거리는 안 쓴다.
